package com.jnapanam.sportszone.notification.model;import com.jnapanam.sportszone.identity.model.User;import jakarta.persistence.*;import java.time.Instant;import java.util.UUID;
@Entity@Table(name="notifications")public class Notification{@Id private UUID id;@ManyToOne(fetch=FetchType.LAZY,optional=false)@JoinColumn(name="user_id")private User user;@Enumerated(EnumType.STRING)@Column(nullable=false,length=20)private NotificationChannel channel;@Column(nullable=false,length=40)private String category;@Column(length=180)private String subject;@Column(nullable=false,columnDefinition="TEXT")private String message;@Enumerated(EnumType.STRING)@Column(nullable=false,length=20)private NotificationStatus status;@Column(nullable=false)private int attempts;@Column(name="provider_message_id",length=160)private String providerMessageId;@Column(name="last_error",length=500)private String lastError;@Column(name="read_at")private Instant readAt;@Column(name="created_at",nullable=false)private Instant createdAt;@Column(name="sent_at")private Instant sentAt;@Column(name="next_attempt_at")private Instant nextAttemptAt;protected Notification(){}public Notification(User u,NotificationChannel c,String category,String subject,String message){id=UUID.randomUUID();user=u;channel=c;this.category=category;this.subject=subject;this.message=message;status=c==NotificationChannel.IN_APP?NotificationStatus.SENT:NotificationStatus.QUEUED;createdAt=Instant.now();if(status==NotificationStatus.SENT)sentAt=createdAt;nextAttemptAt=createdAt;}public void read(){readAt=Instant.now();}public void sent(String id){status=NotificationStatus.SENT;providerMessageId=id;sentAt=Instant.now();attempts++;lastError=null;}public void failed(String error){attempts++;lastError=error==null?"Delivery failed":error.substring(0,Math.min(500,error.length()));nextAttemptAt=Instant.now().plusSeconds(Math.min(3600,60L*attempts));}public UUID getId(){return id;}public User getUser(){return user;}public NotificationChannel getChannel(){return channel;}public String getCategory(){return category;}public String getSubject(){return subject;}public String getMessage(){return message;}public NotificationStatus getStatus(){return status;}public int getAttempts(){return attempts;}public Instant getReadAt(){return readAt;}public Instant getCreatedAt(){return createdAt;}public Instant getSentAt(){return sentAt;}}
